// WhatsAppButton.js
import React, { useState } from 'react';
import styled, { keyframes } from 'styled-components';
import { FaWhatsapp } from 'react-icons/fa';

const WhatsAppButton = () => {
  const [message, setMessage] = useState('');
  const [isOpen, setIsOpen] = useState(false);

  const handleChange = (e) => {
    setMessage(e.target.value);
  };

  const handleClick = () => {
    const url = `https://wa.me/1234567890?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  return (
    <StyledWhatsAppButton>
      <button onClick={() => setIsOpen(!isOpen)}>
        <FaWhatsapp size={24} />
        {!isOpen && <Tooltip>Chat on WhatsApp</Tooltip>}
      </button>
      {isOpen && (
        <MessageContainer>
          <input
            type="text"
            placeholder="Type your message..."
            value={message}
            onChange={handleChange}
          />
          <SendButton onClick={handleClick}>Send</SendButton>
        </MessageContainer>
      )}
    </StyledWhatsAppButton>
  );
};

const slideIn = keyframes`
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
`;

const StyledWhatsAppButton = styled.div`
  position: fixed;
  bottom: 20px;
  right: 20px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;

  button {
    background-color: #25d366;
    color: white;
    border: none;
    padding: 0.5em;
    border-radius: 50%;
    cursor: pointer;
    font-size: 1.2em;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3);
    transition: transform 0.3s;

    &:hover {
      transform: scale(1.1);
    }
  }
`;

const Tooltip = styled.span`
  background-color: #25d366;
  color: white;
  padding: 0.3em 0.6em;
  border-radius: 5px;
  font-size: 0.8em;
  position: absolute;
  bottom: 100%;
  right: 0;
  transform: translateY(-5px);
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.2s ease;

  button:hover & {
    opacity: 1;
  }
`;

const MessageContainer = styled.div`
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  animation: ${slideIn} 0.3s ease forwards;
  margin-top: 0.5em;

  input {
    padding: 0.5em;
    border-radius: 0.5em;
    border: 1px solid #ddd;
    margin-bottom: 0.5em;
    width: 180px;
    outline: none;
  }
`;

const SendButton = styled.button`
  background-color: #25d366;
  color: white;
  border: none;
  padding: 0.5em 1em;
  border-radius: 20px;
  cursor: pointer;
  font-weight: bold;
  transition: background 0.3s;
  align-self: flex-end;

  &:hover {
    background-color: #1ebc5a;
  }
`;

export default WhatsAppButton;
